{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What distance metric should be used to compute travel distances between the depot and customers (e.g., Euclidean straight-line distance, Manhattan distance, or some other metric)?"
  ],
  "rationale": "The response contains a single clarification question asking for the specific distance metric to be used."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Should the travel time between two locations be computed as the distance divided by a constant speed (i.e., travel time proportional to distance), or should I treat the distance values directly as time in minutes?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive methods for calculating travel time."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a truck finishes serving its last customer, must it return to the depot, or is it acceptable for the route to end at the last customer's location?"
  ],
  "rationale": "The response asks for a single policy choice regarding the endpoint of the truck's route, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single truck serve multiple separate routes (i.e., leave the depot, serve some customers, return to the depot, then leave again to serve more customers), or does each truck make exactly one trip from the depot and back?"
  ],
  "rationale": "The response asks for a single policy choice regarding truck routing behavior, presented as a binary alternative within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a truck arrives at a customer before the customer's time window opens, does the waiting time count toward the truck's schedule (i.e., the truck is occupied and cannot serve another customer during the wait), or is waiting time effectively free?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding how waiting time is treated in the schedule."
}

